window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[159]={"id":"159","numero":159,"titre":"Tuberculose de l'adulte et de l'enfant","objectifs":[{"id":"159-1","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les caractéristiques épidémiologiques de la tuberculose et de la résistance du Bacille de Koch (BK)","contenu":"<p>La <span class=\"kw-def\">tuberculose</span> est une <span class=\"kw-def\">maladie infectieuse endémo-épidémique</span> à transmission <strong>interhumaine par voie aérienne</strong>. Sa répartition oppose <span class=\"kw-clinique\">les</span> pays à faible <span class=\"kw-def\">incidence</span> (France) aux zones de forte endémie.</p>\n      <h4><span class=\"kw-def\">Épidémiologie</span></h4>\n      <table >\n        <thead><tr><th>Échelle</th><th>Chiffres clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong>France</strong> (pays à faible <span class=\"kw-def\">incidence</span>)</td><td>≈ <span class=\"kw-chiffre\">4 606 cas</span> déclarés en 2020, soit une <span class=\"kw-def\">incidence</span> de <span class=\"kw-chiffre\">6,8 / 100 000 hab.</span><br>Surreprésentation : <span class=\"kw-etio\">Île-de-France</span> ; <span class=\"kw-etio\">Mayotte</span> ; <span class=\"kw-etio\">Guyane</span></td></tr>\n          <tr><td><strong>Monde</strong></td><td><span class=\"kw-alerte\">3ᵉ cause de mortalité par maladie infectieuse</span> : ≈ <span class=\"kw-chiffre\">1,4 million</span> de décès/an ; ≈ <span class=\"kw-chiffre\">10 millions</span> de nouveaux cas/an</td></tr>\n          <tr><td><strong>Zones d'endémie</strong></td><td><strong>Afrique subsaharienne :</strong> <span class=\"kw-chiffre\">300-1000 / 100 000</span>/an<br><strong>Asie, Europe centrale et de l'Est :</strong> <span class=\"kw-chiffre\">100-300 / 100 000</span><br><strong>Amérique latine :</strong> <span class=\"kw-chiffre\">25-100 / 100 000</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Résistance du BK aux antituberculeux</h4>\n      <p>Au sein de la population sauvage de <em>M. tuberculosis</em> préexistent des <span class=\"kw-def\">mutants résistants naturels</span> (mutation aléatoire, hors de toute <span class=\"kw-ttt\">antibiothérapie</span>) : ≈ <span class=\"kw-chiffre\">1/10⁵</span> pour l'<span class=\"kw-ttt\">isoniazide</span>, ≈ <span class=\"kw-chiffre\">1/10⁷</span> pour la <span class=\"kw-ttt\">rifampicine</span>. Une caverne contient jusqu'à <span class=\"kw-chiffre\">10⁸</span> bacilles — c'est ce qui <strong>justifie la polythérapie</strong> : la probabilité d'un double mutant est le produit des deux (≈ <span class=\"kw-chiffre\">10⁻¹²</span>).</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">Tuberculose</span> MDR</th><th><span class=\"kw-def\">Tuberculose</span> XDR</th></tr></thead>\n        <tbody>\n          <tr><td>Définition</td><td>Résistance à l'<span class=\"kw-ttt\">INH</span> + la <span class=\"kw-ttt\">RMP</span></td><td>MDR + résistance à <strong>toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">fluoroquinolones</span></strong> + <span class=\"kw-chiffre\">≥ 1</span> injectable de 2ᵉ ligne</td></tr>\n          <tr><td>En France</td><td>≈ <span class=\"kw-chiffre\">2 %</span> des cas (≈ 100/an)</td><td><span class=\"kw-chiffre\">10-20</span> cas/an, <span class=\"kw-alerte\">mortalité élevée</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>FR de résistance.</strong> <span class=\"kw-alerte\">Défaut d'observance</span> = facteur principal · origine géographique (pays de l'ex-URSS, Chine, Inde) · ATCD personnel de <span class=\"kw-def\">tuberculose</span>, surtout si le traitement a été interrompu.</div>","frequence":2},{"id":"159-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la tuberculose et les caractéristiques microbiologiques des mycobactéries","contenu":"<p>La <span class=\"kw-def\">tuberculose</span> est une <span class=\"kw-def\">maladie infectieuse</span> due aux mycobactéries du <span class=\"kw-etio\">complexe Mycobacterium tuberculosis</span>. Deux entités sont à distinguer :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Infection tuberculeuse latente (ITL)</span></strong> — <span class=\"kw-clinique\">primo-infection</span> asymptomatique, <span class=\"kw-alerte\">non contagieuse</span> ; bacilles quiescents contenus dans le granulome.</li>\n        <li><strong><span class=\"kw-etio\">Tuberculose maladie (TM)</span></strong> — forme symptomatique, <span class=\"kw-alerte\">contagieuse</span> dans sa forme pulmonaire.</li>\n      </ul>\n      <h4>Caractéristiques microbiologiques</h4>\n      <ul>\n        <li><span class=\"kw-bio\">BAAR</span> — bacille acido-alcoolo-résistant.</li>\n        <li>Croissance <strong>lente</strong> ; métabolisme <strong><span class=\"kw-def\">aérobie strict</span></strong> ; multiplication intra- <strong>et</strong> extracellulaire.</li>\n        <li>Localisation préférentielle <strong>pulmonaire</strong> (mais tout organe peut être touché).</li>\n      </ul>\n      <p>Le complexe <em>M. tuberculosis</em> regroupe <span class=\"kw-chiffre\">7 espèces</span> :</p>\n      <table >\n        <thead><tr><th>Espèce</th><th>Part des cas</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">M. tuberculosis hominis</span> = bacille de Koch (BK)</td><td><span class=\"kw-chiffre\">95 %</span></td></tr>\n          <tr><td><em>M. bovis</em></td><td><span class=\"kw-chiffre\">1 %</span></td></tr>\n          <tr><td><em>M. africanum</em></td><td>plus rare</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Seules <span class=\"kw-clinique\">les</span> <em>M. tuberculosis</em> sont des <span class=\"kw-def\">pathogènes stricts</span> — les autres mycobactéries peuvent être commensales.</div>","frequence":0},{"id":"159-3","rang":"A","rubrique":"Étiologies","titre":"Connaître les facteurs de risque de la tuberculose","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">facteurs de risque</span> se déclinent en risque d'<strong>infection</strong> et risque de <strong>passage ITL → TM</strong>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âges extrêmes</strong></td><td>Enfant <span class=\"kw-chiffre\">&lt; 5 ans</span> ; sujet âgé</td></tr>\n          <tr><td><strong>Origine</strong></td><td>Émigration depuis une <span class=\"kw-etio\">zone de forte endémie</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Comorbidités</span></strong></td><td><span class=\"kw-etio\">Diabète</span> ; <span class=\"kw-ci\">insuffisance rénale</span> ; <span class=\"kw-alerte\">immunodépression</span> — <span class=\"kw-etio\">VIH</span> ++, <span class=\"kw-ttt\">anti-TNF-α</span>, transplantés d'organe solide</td></tr>\n          <tr><td><strong>Mode de vie</strong></td><td><span class=\"kw-etio\">Alcoolisme</span> ; <span class=\"kw-etio\">tabac</span> ; <span class=\"kw-etio\">dénutrition</span> ; conditions socio-économiques défavorables (précarité, toxicomanie, SDF, migrants, milieu carcéral)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Passage ITL → TM.</strong> Risque majoré par l'<span class=\"kw-alerte\">immunodépression (VIH +++)</span>, <span class=\"kw-clinique\">les</span> âges extrêmes, le <span class=\"kw-def\">diabète</span> / l'<span class=\"kw-def\">IRC</span> / la malnutrition / l'<span class=\"kw-etio\">alcoolisme</span>, la précarité. ≈ <span class=\"kw-chiffre\">10 %</span> des ITL évoluent vers une TM, surtout dans les <span class=\"kw-chiffre\">2 premières années</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 174 — Pathologie infectieuse du migrant</em></p>","frequence":1},{"id":"159-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les différentes modalités évolutives de la tuberculose","contenu":"<p>L'histoire naturelle se déroule en <strong>3 étapes</strong> :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Contamination</strong></td><td>Inhalation d'aérosols de <span class=\"kw-def\">gouttelettes</span> infectantes. Risque proportionnel à : <strong>intensité de la <span class=\"kw-clinique\">toux</span></strong> ; <strong>contagiosité du cas</strong> (<span class=\"kw-clinique\">BAAR</span> à l'examen direct, cavernes) ; <strong>durée d'exposition</strong>. Seul <span class=\"kw-chiffre\">1/3</span> des exposés développe une <span class=\"kw-clinique\">primo-infection</span>.</td></tr>\n          <tr><td><strong>2. PIT → ITL</strong></td><td><span class=\"kw-clinique\">Primo-infection</span> tuberculeuse le plus souvent <span class=\"kw-alerte\">asymptomatique</span> = <span class=\"kw-etio\">infection tuberculeuse latente</span>. Formation d'un <span class=\"kw-def\">granulome giganto-cellulaire avec nécrose caséeuse</span> contenant des <span class=\"kw-def\">bacilles quiescents</span>.</td></tr>\n          <tr><td><strong>3. <span class=\"kw-def\">Tuberculose</span> maladie</strong></td><td>Réactivation possible à tout moment. <span class=\"kw-chiffre\">≈ 10 %</span> des PIT évoluent vers une TM — <span class=\"kw-chiffre\">≈ 5 %</span> dans <span class=\"kw-clinique\">les</span> 2 premières années, <span class=\"kw-chiffre\">≈ 5 %</span> au-delà.</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-etio\">tuberculose maladie</span> prend 3 formes selon la voie de dissémination :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Tuberculose</span> pulmonaire commune</strong> — voie <span class=\"kw-def\">bronchogène</span> (fistulisation d'un ganglion ou d'un foyer).</li>\n        <li><strong>Miliaire tuberculeuse</strong> — voie <span class=\"kw-def\">hématogène</span> (ensemencement multiviscéral).</li>\n        <li><strong><span class=\"kw-def\">Tuberculose</span> extra-pulmonaire</strong> — voie <span class=\"kw-def\">lymphatique ou hématogène</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> En l'absence d'immunodépression, <span class=\"kw-chiffre\">≈ 90 %</span> des PIT guérissent : le granulome involue et se calcifie.</div>\n      <h4><span class=\"kw-def\">Chimioprophylaxie</span> de l'ITL (traitement de l'ITL)</h4>\n      <p>Objectif : <strong>limiter le passage d'une ITL vers une TM</strong>. Trois schémas possibles, mêmes précautions et <span class=\"kw-def\">surveillance</span> que le traitement d'une TM :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Isoniazide</span> en monothérapie pendant <span class=\"kw-chiffre\">6 mois</span>.</li>\n        <li><span class=\"kw-ttt\">Rifampicine</span> en monothérapie pendant <span class=\"kw-chiffre\">4 mois</span>.</li>\n        <li><span class=\"kw-ttt\">Rifampicine</span> + <span class=\"kw-ttt\">isoniazide</span> pendant <span class=\"kw-chiffre\">3-4 mois</span>.</li>\n      </ul>\n      <p><strong>Indications :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Chimioprophylaxie</span> primaire : <span class=\"kw-alerte\">enfant &lt; 2 ans</span> ; <span class=\"kw-alerte\">immunodéprimé sévère</span> exposé à un sujet bacillifère.</li>\n        <li><span class=\"kw-def\">Chimioprophylaxie</span> secondaire : <strong>ITL chez le sujet &lt;<span class=\"kw-chiffre\"> 18 ans</span></strong> (+ déclaration obl<span class=\"kw-chiffre\">iga</span>toire) ; ITL chez l'<span class=\"kw-alerte\">immunodéprimé</span> ; <strong>ITL récente</strong> (&lt;<span class=\"kw-chiffre\"> 2 ans</span>, dépistée lors d'une <span class=\"kw-def\">enquête autour d'un cas</span>).</li>\n      </ul>","frequence":0},{"id":"159-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’indication d’une intradermo-réaction (IDR) à la tuberculine, d’un test IGRA (Interferon Gamma Release Assays)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">tests immunologiques</span> (<span class=\"kw-clinique\">IDR</span> et IGRA) explorent la <strong>réponse immune d'<span class=\"kw-ci\">hypersensibilité</span> retardée à médiation cellulaire</strong> induite par le BK (positivité <span class=\"kw-chiffre\">6-12 semaines</span> après le contage).</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ces tests <span class=\"kw-alerte\">n'ont pas d'intérêt pour diagnostiquer une tuberculose maladie</span> : ils ne distinguent pas une ITL d'une TM, et leur négativité n'élimine pas une TM (sensibilité ≈ <span class=\"kw-chiffre\">70 %</span>). Leur rôle = <strong>dépister <span class=\"kw-clinique\">les</span> ITL à haut risque d'<span class=\"kw-clinique\">évolution</span></strong>. Toujours éliminer une TM au préalable (clinique + <span class=\"kw-imagerie\">RXT</span> ± prélèvements respiratoires).</div>\n      <p><strong>Indications respectives</strong> selon la situation :</p>\n      <table >\n        <thead><tr><th>Situation</th><th><span class=\"kw-clinique\">IDR</span></th><th>IGRA</th></tr></thead>\n        <tbody>\n          <tr><td>Migrant mineur de zone d'endémie</td><td>Oui (si arrivé en France &lt;<span class=\"kw-chiffre\"> 5 ans</span>)</td><td>Oui (si arrivé en France &lt;<span class=\"kw-chiffre\"> 5 ans</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Enquête autour d'un cas</span></td><td>Oui</td><td>Oui</td></tr>\n          <tr><td>Avant <span class=\"kw-ttt\">anti-TNF-α</span></td><td>Non</td><td><strong>Oui</strong> (préféré)</td></tr>\n          <tr><td>Séropositivité <span class=\"kw-etio\">VIH</span></td><td>Non</td><td><strong>Oui</strong></td></tr>\n          <tr><td>Professionnel de santé</td><td>Oui, à l'embauche</td><td>Utile si vacciné BCG (non remboursé)</td></tr>\n          <tr><td>Aide au diagnostic de TM pauci-bacillaire</td><td>Non</td><td>Oui (enfant, forme extra-pulmonaire)</td></tr>\n        </tbody>\n      </table>\n      <p>Deux mesures différentes : l'<span class=\"kw-bio\">IDR à la tuberculine</span> mesure une réponse <strong>in vivo</strong> (induration lue à <span class=\"kw-chiffre\">J2</span>-J3 après injection intradermique ; <span class=\"kw-alerte\">faux positifs</span> avec le <span class=\"kw-ttt\">BCG</span>, <em>M. bovis</em> et certaines mycobactéries atypiques) ; l'<span class=\"kw-bio\">IGRA</span> mesure une réponse <strong>in vitro</strong> (production d'<span class=\"kw-bio\">IFN-γ</span> ; ne croise pas le BCG, une seule prise de sang).</p>\n      <h4>Interprétation de l'<span class=\"kw-clinique\">IDR</span> (en mm d'induration)</h4>\n      <table >\n        <thead><tr><th>Résultat</th><th>Seuil d'induration</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">IDR</span> négative</strong></td><td><span class=\"kw-clinique\">Diamètre</span> <span class=\"kw-chiffre\">&lt; 5 mm</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">IDR</span> positive</strong></td><td><span class=\"kw-clinique\">Diamètre</span> <span class=\"kw-chiffre\">≥ 5 mm</span></td></tr>\n          <tr><td><strong>Suspicion d'ITL</strong> — non vacciné (ou BCG &gt;<span class=\"kw-chiffre\"> 10 ans</span>)</td><td><span class=\"kw-clinique\">Diamètre</span> <span class=\"kw-chiffre\">&gt; 10 mm</span></td></tr>\n          <tr><td><strong>Suspicion d'ITL</strong> — vacciné BCG depuis &lt;<span class=\"kw-chiffre\"> 10 ans</span></td><td><span class=\"kw-clinique\">Diamètre</span> <span class=\"kw-chiffre\">&gt; 15 mm</span></td></tr>\n          <tr><td><strong>Virage tuberculinique</strong></td><td>Augmentation de l'induration de <span class=\"kw-chiffre\">&gt; 10 mm</span> entre 2 <span class=\"kw-clinique\">IDR</span> à <span class=\"kw-chiffre\">2-3 mois</span> d'intervalle</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"159-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique d’une primo infection tuberculeuse","contenu":"<p>La <span class=\"kw-etio\">primo-infection tuberculeuse (PIT)</span> est <strong>asymptomatique dans la grande majorité des cas</strong> (= ITL). Incubation : <span class=\"kw-chiffre\">1 à 3 mois</span>.</p>\n      <p>Quand elle est <strong>patente</strong>, elle associe (de haut en bas) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre modérée</span> ; <span class=\"kw-clinique\">altération minime de l'état général</span>.</li>\n        <li><span class=\"kw-clinique\">Kérato-conjonctivite phlycténulaire</span>.</li>\n        <li><span class=\"kw-clinique\">Adénopathies cervicales</span>.</li>\n        <li><span class=\"kw-clinique\">Pleurésie séro-fibrineuse</span>.</li>\n        <li><span class=\"kw-clinique\">Érythème noueux</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-imagerie\">RXT</span> peut montrer des <span class=\"kw-radio\">adénopathies médiastinales</span> ± <span class=\"kw-clinique\">lésion</span> parenchymateuse correspondant au foyer primaire (« <span class=\"kw-clinique\">chancre d'inoculation</span> »). À ce <span class=\"kw-def\">stade</span>, le <span class=\"kw-alerte\">BK n'est jamais isolé dans l'expectoration</span>.</div>","frequence":0},{"id":"159-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique d’une tuberculose maladie","contenu":"<h4><span class=\"kw-def\">Tuberculose</span> pulmonaire commune</h4>\n      <p><span class=\"kw-clinique\">Évolution</span> <strong>insidieuse, subaiguë</strong>, sur plusieurs <span class=\"kw-chiffre\">semaines à mois</span>.</p>\n      <table >\n        <thead><tr><th>Type de signe</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Généraux</strong></td><td><span class=\"kw-clinique\">AEG</span> (<span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">amaigrissement</span>) ; <span class=\"kw-clinique\">fébricule</span> à prédominance nocturne ; <span class=\"kw-clinique\">sueurs nocturnes</span></td></tr>\n          <tr><td><strong>Fonctionnels</strong></td><td><span class=\"kw-clinique\">Toux chronique</span> ± <span class=\"kw-clinique\">expectoration</span> ; <span class=\"kw-clinique\">hémoptysie</span> (du crachat hémoptoïque à l'<span class=\"kw-clinique\">hémoptysie</span> grave) ; <span class=\"kw-clinique\">dyspnée</span> tardive ; <span class=\"kw-clinique\">douleur thoracique</span> peu fréquente</td></tr>\n          <tr><td><strong>Physiques</strong></td><td>Le plus souvent <strong>absents</strong> ; syndrome pleural si pleurésie associée</td></tr>\n        </tbody>\n      </table>\n      <h4>Miliaire tuberculeuse</h4>\n      <p>Forme <span class=\"kw-alerte\">disséminée par voie hématogène</span> : <span class=\"kw-clinique\">AEG marquée</span>, <span class=\"kw-clinique\">fièvre prolongée</span>, <span class=\"kw-clinique\">sueurs nocturnes</span>, possible <span class=\"kw-alerte\">SDRA</span>, signes neuro-méningés (nourrisson), péricardite.</p>\n      <div class=\"callout callout-warn\"><strong>Particularités pédiatriques.</strong> Symptômes peu spécifiques mais traînants : <span class=\"kw-clinique\">cassure pondérale</span> inexpliquée ; <span class=\"kw-clinique\">léthargie</span> ou baisse d'activité ; <span class=\"kw-clinique\">état subfébrile prolongé</span> ; infection bronchopulmonaire résistante aux antibiotiques usuels. Aspect <span class=\"kw-alerte\">pseudo-septique avec hépato-splénomégalie</span> possible chez le nourrisson de <span class=\"kw-chiffre\">&lt; 3 mois</span>.</div>","frequence":3},{"id":"159-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique de la tuberculose extra-pulmonaire","contenu":"<p><span class=\"kw-clinique\">Les</span> formes extra-pulmonaires représentent <span class=\"kw-chiffre\">≈ 30 %</span> des tuberculoses maladie. Elles sont plus fréquentes chez l'<strong>enfant</strong> et l'<strong>immunodéprimé</strong> (diagnostic plus difficile).</p>\n      <p><strong>Ordre de fréquence :</strong> ganglionnaire &gt; ostéo-rachidienne &gt; neuro-méningée &gt; séreuses &gt; uro-génitale / digestive / ORL.</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Ganglionnaire</strong></td><td>La plus fréquente, <strong>enfant ++</strong> ; adénites basi-cervicales ou médiastinales ; risque de <span class=\"kw-alerte\">fistulisation à la peau</span></td></tr>\n          <tr><td><strong>Ostéo-rachidienne</strong></td><td><span class=\"kw-etio\">Mal de Pott</span> (spondylodiscite) d'<span class=\"kw-clinique\">évolution</span> chronique ; risque d'<span class=\"kw-alerte\">épidurite</span>, de <span class=\"kw-alerte\">compression médullaire</span>, de tassements vertébraux</td></tr>\n          <tr><td><strong>Neuro-méningée</strong></td><td><span class=\"kw-clinique\">Méningite basilaire</span> (atteinte des nerfs crâniens, troubles végétatifs) ; <span class=\"kw-bio\">SIADH</span> ; <span class=\"kw-bio\">LCS</span> clair lymphocytaire, <span class=\"kw-bio\">hyperprotéinorachie</span>, <span class=\"kw-bio\">hypoglycorachie</span></td></tr>\n          <tr><td><strong>Séreuses</strong></td><td>Pleurésie (liquide citrin exsudatif lymphocytaire) ; péricardite (risque de <span class=\"kw-alerte\">tamponnade</span> et de <span class=\"kw-alerte\">constriction</span>) ; péritoine (<span class=\"kw-clinique\">ascite</span> riche en protéines &gt;<span class=\"kw-chiffre\"> 25 g/L</span>)</td></tr>\n          <tr><td><strong>Uro-génitale</strong></td><td><span class=\"kw-bio\">Leucocyturie aseptique</span> ; risque de <span class=\"kw-alerte\">stérilité</span> par synéchies</td></tr>\n          <tr><td><strong>Surrénalienne</strong></td><td><span class=\"kw-alerte\">2ᵉ cause d'insuffisance surrénale primitive</span> ; surrénales augmentées de taille puis atrophiées / calcifiées</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/159/tdm-tb-surrenaliennes.png\" alt=\"TDM abdominale — surrénales augmentées de taille de façon bilatérale au cours d'une tuberculose surrénalienne\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> abdominale : surrénales augmentées de taille de façon bilatérale — <span class=\"kw-def\">tuberculose</span> surrénalienne, responsable d'une insuffisance surrénale primaire chronique. Source : fiche source EDN item 159 — <span class=\"kw-def\">Tuberculose</span>.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 206 — Epanchement pleural · 235 — Péricardite aiguë · 245 — Insuffisance surrénale</em></p>","frequence":1},{"id":"159-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser au cours d’une tuberculose maladie pulmonaire","contenu":"<h4>Prélèvements respiratoires</h4>\n      <ul>\n        <li><strong>Si le patient crache :</strong> <span class=\"kw-bio\">ECBC</span> avec recherche <strong>spécifique de <span class=\"kw-clinique\">BAAR</span></strong>, <span class=\"kw-chiffre\">3 prélèvements</span> — la recherche de BAAR n'est <span class=\"kw-alerte\">pas faite sur un ECBC standard</span>, il faut la préciser.</li>\n        <li><strong>S'il ne crache pas :</strong> <span class=\"kw-bio\">tubage gastrique</span> le matin à jeun, <span class=\"kw-chiffre\">3 jours de suite</span> (<span class=\"kw-clinique\">les</span> sécrétions avalées la nuit contiennent des <span class=\"kw-clinique\">BAAR</span> résistants à l'acidité gastrique).</li>\n        <li><strong><span class=\"kw-imagerie\">Fibroscopie</span> bronchique + <span class=\"kw-bio\">LBA</span></strong> si 3 prélèvements négatifs à l'examen direct, ou si suspicion de miliaire.</li>\n      </ul>\n      <h4>Mycobactériologie</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Examen direct</strong></td><td>Coloration de <span class=\"kw-bio\">Ziehl-Neelsen</span> ; positif si &gt; <span class=\"kw-chiffre\">10³ BAAR/mL</span> ; résultat en quelques heures ; <span class=\"kw-alerte\">une négativité n'élimine pas le diagnostic</span></td></tr>\n          <tr><td><strong>Culture</strong></td><td>Milieu solide de <span class=\"kw-bio\">Löwenstein-Jensen</span> : positive à <span class=\"kw-chiffre\">3-4 semaines</span> ; milieu liquide : <span class=\"kw-chiffre\">10-15 jours</span></td></tr>\n          <tr><td><strong>Test génotypique (<span class=\"kw-bio\">PCR</span>)</strong></td><td>Sur <strong>tout examen direct ou culture positif</strong>, dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 72 h</span> : confirme le complexe tuberculosis + recherche les mutations de résistance (ex. gène <em>rpoB</em> → <span class=\"kw-ttt\">rifampicine</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Antibiogramme</span></strong></td><td><strong>Obl<span class=\"kw-chiffre\">iga</span>toire</strong> ; peut nécessiter plusieurs semaines (voire mois) de culture. Si une <span class=\"kw-alerte\">résistance est suspectée</span>, la souche est adressée au <span class=\"kw-def\">CNR</span> (Centre national de référence) des mycobactéries pour tester <span class=\"kw-clinique\">les</span> antituberculeux de 2ᵉ ligne</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-bio\">Anatomopathologie</span> :</strong> <span class=\"kw-def\">granulome épithélioïde giganto-cellulaire avec nécrose caséeuse</span> — fortement évocateur mais <span class=\"kw-alerte\">non pathognomonique</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Chez l'enfant.</strong> La TM est <span class=\"kw-alerte\">pauci-bacillaire</span> : examen direct positif dans <span class=\"kw-chiffre\">&lt; 20 %</span> des cas, culture <span class=\"kw-chiffre\">&lt; 50 %</span>. Le diagnostic repose souvent sur un <strong>faisceau d'arguments</strong> (contage, clinique, réponse immunitaire, <span class=\"kw-imagerie\">RXT</span>).</div>","frequence":3},{"id":"159-10","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie pulmonaire au cours d’une tuberculose pulmonaire maladie","contenu":"<p>La <span class=\"kw-imagerie\">radiographie thoracique</span> est l'examen d'orientation de <span class=\"kw-chiffre\">première intention</span>. Trois types de lésions, pouvant s'associer :</p>\n      <ul>\n        <li><span class=\"kw-radio\">Nodules</span> (tuberculome).</li>\n        <li><span class=\"kw-radio\">Infiltrats</span>.</li>\n        <li><span class=\"kw-radio\">Cavernes</span> — <span class=\"kw-clinique\">lésion</span> excavée, <span class=\"kw-alerte\">forme la plus productrice de bacilles</span> et principale source de transmission.</li>\n      </ul>\n      <p><strong>Localisations préférentielles :</strong> <span class=\"kw-clinique\">les</span> <strong>lobes les mieux ventilés</strong> — sommets et segments postérieurs.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/159/rxt-tb-pulmonaire-cavernes.png\" alt=\"Radiographie thoracique de face — opacités hétérogènes excavées du lobe supérieur droit au cours d'une tuberculose pulmonaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie thoracique</span> de face : opacités hétérogènes et infiltrats du lobe supérieur droit avec aspect excavé — <span class=\"kw-def\">tuberculose</span> pulmonaire commune. Source : fiche source EDN item 159 — <span class=\"kw-def\">Tuberculose</span>.</figcaption>\n      </figure>\n      <p>La <span class=\"kw-etio\">miliaire tuberculeuse</span> se traduit par un <span class=\"kw-radio\">semis de micronodules</span> à contours nets, de distribution diffuse aux deux champs pulmonaires.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/159/rxt-miliaire.png\" alt=\"Radiographie thoracique — semis de micronodules diffus au cours d'une miliaire tuberculeuse\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie thoracique</span> (agrandissement) : semis de micronodules diffus de petite taille — aspect de miliaire tuberculeuse. Source : fiche source EDN item 159 — <span class=\"kw-def\">Tuberculose</span>.</figcaption>\n      </figure>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/tuberculosis","label":"Radiopaedia : Tuberculosis"},{"href":"https://radiopaedia.org/articles/tuberculosis-pulmonary-manifestations-1","label":"Radiopaedia : TB pulmonary manifestations"},{"href":"https://radiopaedia.org/articles/miliary-tuberculosis","label":"Radiopaedia : Miliary tuberculosis"},{"href":"https://radiopaedia.org/articles/adrenal-tuberculosis","label":"Radiopaedia : Adrenal tuberculosis"},{"href":"https://radiopaedia.org/cases/thoracic-tuberculosis-paediatric-1","label":"Radiopaedia : Thoracic TB pédiatrique (cas)"}]},{"id":"159-11","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie au cours d’une tuberculose maladie pulmonaire","contenu":"<p>La <span class=\"kw-imagerie\">tomodensitométrie thoracique</span> intervient en <strong>2ᵉ intention</strong> : elle précise <span class=\"kw-clinique\">les</span> lésions mal vues sur la <span class=\"kw-imagerie\">radiographie</span> et caractérise la dissémination.</p>\n      <ul>\n        <li><span class=\"kw-radio\">Cavernes</span> à paroi épaisse.</li>\n        <li><span class=\"kw-radio\">Micronodules de dissémination bronchogène</span> — aspect d'« arbre en bourgeon ».</li>\n        <li><span class=\"kw-radio\">Micronodulation diffuse</span> bilatérale dans la miliaire.</li>\n        <li><span class=\"kw-radio\">Adénopathies médiastinales</span> — chez l'enfant : centre hypodense (<span class=\"kw-clinique\">nécrose</span>), périphérie rehaussée après injection.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/159/tdm-tb-pulmonaire.png\" alt=\"TDM thoracique axiale — caverne du lobe supérieur et micronodules satellites de dissémination bronchogène\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> thoracique, coupe axiale (fenêtre parenchymateuse) : caverne à paroi épaisse + micronodules satellites de dissémination bronchogène. Source : fiche source EDN item 159 — <span class=\"kw-def\">Tuberculose</span>.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/159/rxt-tb-pulmonaire-secondaire.png\" alt=\"TDM thoracique axiale — caverne pulmonaire et nodules de dissémination bronchogène\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> thoracique, coupe axiale : caverne pulmonaire et nodules de dissémination bronchogène (« arbre en bourgeon »). Source : fiche source EDN item 159 — <span class=\"kw-def\">Tuberculose</span>.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/159/tdm-miliaire.png\" alt=\"TDM thoracique axiale — micronodulation diffuse bilatérale au cours d'une miliaire tuberculeuse\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> thoracique, coupe axiale : micronodulation diffuse bilatérale des deux poumons — miliaire tuberculeuse. Source : fiche source EDN item 159 — <span class=\"kw-def\">Tuberculose</span>.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/159/rxt-tb-pediatrique-adenopathies.png\" alt=\"TDM thoracique injectée chez l'enfant — volumineuses adénopathies médiastinales et latérotrachéales\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> thoracique injectée, enfant : volumineuses <span class=\"kw-clinique\">adénopathies</span> médiastinales et latérotrachéales — présentation typique de la <span class=\"kw-def\">tuberculose</span> de l'enfant, pouvant comprimer <span class=\"kw-clinique\">les</span> voies aériennes adjacentes. Source : fiche source EDN item 159 — <span class=\"kw-def\">Tuberculose</span>.</figcaption>\n      </figure>","frequence":2},{"id":"159-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux du traitement de la tuberculose","contenu":"<h4>Schémas thérapeutiques</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Schéma</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Schéma classique</strong></td><td>Quadrithérapie <span class=\"kw-ttt\">INH + RMP + EMB + PZA</span> pendant <span class=\"kw-chiffre\">2 mois</span>, puis bithérapie <span class=\"kw-ttt\">INH + RMP</span> pendant <span class=\"kw-chiffre\">4 mois</span> → <strong><span class=\"kw-chiffre\">6 mois</span> au total</strong></td></tr>\n          <tr><td><strong>Forme neuro-méningée</strong></td><td>Phase de continuation prolongée → <span class=\"kw-chiffre\">9 à 12 mois</span> au total</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Tuberculose</span> multi-résistante</strong></td><td><span class=\"kw-chiffre\">18 à 24 mois</span> avec antituberculeux de 2ᵉ ligne</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Principes du traitement antituberculeux :</strong></p>\n      <ul>\n        <li><strong>Polythérapie obl<span class=\"kw-chiffre\">iga</span>toire</strong> — prévient l'émergence de résistances.</li>\n        <li><strong>Observance capitale</strong> — son défaut expose à la rechute et aux souches résistantes.</li>\n        <li>Prise <strong>unique quotidienne, à jeun</strong> ; traitement <strong>prolongé</strong> ; adapté à l'<span class=\"kw-bio\">antibiogramme</span> dès réception.</li>\n      </ul>\n      <h4>Mesures associées</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> initiale de tout malade suspect de <span class=\"kw-def\">tuberculose</span> pulmonaire, avec <span class=\"kw-alerte\">précautions Air</span>.</li>\n        <li>Prise en charge à <span class=\"kw-chiffre\">100 %</span> (<span class=\"kw-def\">ALD</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ttt\">Corticothérapie</span> adjuvante.</strong> <span class=\"kw-alerte\">Systématique</span> dans la forme <strong>neuro-méningée</strong> ; proposée dans la <strong>péricardite</strong> ; à discuter en cas de <strong>miliaire</strong>, de <span class=\"kw-alerte\">signes de gravité</span> ou de compression mécanique (obstruction bronchique de l'enfant).</div>","frequence":2},{"id":"159-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités d’administration des anti-tuberculeux","contenu":"<p><span class=\"kw-clinique\">Les</span> modalités de prise conditionnent l'efficacité et l'observance :</p>\n      <ul>\n        <li><strong>Prise unique quotidienne</strong> — le temps de dédoublement du BK est long (≈<span class=\"kw-chiffre\"> 20 h</span>).</li>\n        <li><strong>À jeun</strong> — <span class=\"kw-chiffre\">30 min à 1 h</span> avant le repas (ou <span class=\"kw-chiffre\">2 h</span> après) : l'absorption de la <span class=\"kw-ttt\">rifampicine</span> est diminuée par <span class=\"kw-clinique\">les</span> repas.</li>\n        <li><strong>Formes combinées</strong> pour favoriser l'observance : <span class=\"kw-ttt\">Rifater</span> (INH + RMP + PZA), <span class=\"kw-ttt\">Rifinah</span> (INH + RMP).</li>\n      </ul>\n      <h4><span class=\"kw-ci\">Bilan pré-thérapeutique</span></h4>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">bilan rénal</span> (<span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">DFG</span>) ; <span class=\"kw-bio\">transaminases</span> ; <span class=\"kw-bio\">uricémie</span>.</li>\n        <li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span> proposées systématiquement.</li>\n        <li><span class=\"kw-imagerie\">Examen ophtalmologique</span> avant <span class=\"kw-ttt\">éthambutol</span> (champ visuel, vision des couleurs) ; <span class=\"kw-bio\">β-hCG</span> chez la femme en âge de procréer.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Adaptation au <span class=\"kw-def\">terrain</span>.</strong> <span class=\"kw-ci\">Grossesse</span> : traitement identique (pas de <span class=\"kw-ci\">tératogénicité</span>) + supplémentation B6 sous INH, vitamine K1 sous RMP au dernier trimestre. Insuffisance hépatique : pas de PZA si transaminases &gt; 3N, pas d'INH si &gt; 5N. Insuffisance rénale : adapter PZA et EMB si <span class=\"kw-bio\">DFG</span> &lt;<span class=\"kw-chiffre\"> 30 mL</span>/min.</div>","frequence":0},{"id":"159-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales caractéristiques des anti-tuberculeux (toxicité, interactions médicamenteuses, contre-indications, surveillance, précaution d’emploi)","contenu":"<p>Quatre antituberculeux de 1ʳᵉ ligne — <span class=\"kw-ttt\">RMP</span>, <span class=\"kw-ttt\">INH</span>, <span class=\"kw-ttt\">PZA</span>, <span class=\"kw-ttt\">EMB</span> — dont il faut connaître toxicité, interactions, <span class=\"kw-ci\">contre-indications</span> et <span class=\"kw-def\">surveillance</span>.</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-ttt\">Rifampicine</span> (RMP)</th><th><span class=\"kw-ttt\">Isoniazide</span> (INH)</th><th><span class=\"kw-ttt\">Pyrazinamide</span> (PZA)</th><th><span class=\"kw-ttt\">Éthambutol</span> (EMB)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Effets indésirables</strong></td>\n            <td><span class=\"kw-alerte\">Cytolyse hépatique</span> ; coloration <strong>orange</strong> des liquides biologiques (bénigne, prévenir le patient) ; réactions immuno-allergiques (syndrome pseudo-grippal, thrombopénie, anémie hémolytique)</td>\n            <td><span class=\"kw-alerte\">Cytolyse hépatique</span> ; <span class=\"kw-alerte\">neuropathie périphérique</span> (par carence en B6) ; troubles psychiques</td>\n            <td><span class=\"kw-alerte\">Hépatite toxique</span> (plus tardive que l'INH) ; <span class=\"kw-bio\">hyperuricémie</span> quasi constante, asymptomatique, crise de goutte possible — <strong>sans</strong> risque de colique néphrétique</td>\n            <td><span class=\"kw-alerte\">Névrite optique rétrobulbaire</span> — signe d'alerte : <span class=\"kw-alerte\">dyschromatopsie rouge-vert</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Contre-indications</span></strong></td>\n            <td><span class=\"kw-ci\">Insuffisance hépatique majeure</span> ; <span class=\"kw-ci\">porphyrie</span> ; <span class=\"kw-ci\">hypersensibilité</span></td>\n            <td>Arrêt si <span class=\"kw-chiffre\">transaminases &gt; 5N</span></td>\n            <td><span class=\"kw-ci\">Insuffisance hépatocellulaire</span> ; <span class=\"kw-ci\">insuffisance rénale</span></td>\n            <td><span class=\"kw-ci\">Névrite optique</span> préexistante ; <span class=\"kw-ci\">insuffisance rénale</span> sévère</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span></strong></td>\n            <td>Transaminases</td>\n            <td>Transaminases ; examen des ROT</td>\n            <td>Transaminases ; <span class=\"kw-bio\">uricémie</span></td>\n            <td><span class=\"kw-imagerie\">Champ visuel</span> ; vision des couleurs (Farnsworth) ; <span class=\"kw-imagerie\">fond d'œil</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Précaution d'emploi</span></strong></td>\n            <td>Vitamine K1 (mère + enfant) si prescription au dernier trimestre de <span class=\"kw-ci\">grossesse</span></td>\n            <td>Vitamine B6 chez le sujet à risque (<span class=\"kw-ci\">grossesse</span>, <span class=\"kw-etio\">alcoolisme</span>, dénutrition, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-ci\">insuffisance rénale</span>)</td>\n            <td><span class=\"kw-ci\">Allaitement</span> déconseillé (au cas par cas)</td>\n            <td>Arrêté dès la confirmation de la sensibilité de la souche à l'<span class=\"kw-ttt\">isoniazide</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Interactions de la <span class=\"kw-ttt\">rifampicine</span>.</strong> <span class=\"kw-alerte\">Puissant inducteur des CYP</span> → diminue l'efficacité de nombreux médicaments : <span class=\"kw-ci\">anticoagulants</span>, <span class=\"kw-ci\">contraception œstroprogestative</span>, <span class=\"kw-ci\">antirétroviraux</span>, <span class=\"kw-ci\">corticoïdes</span>, méthadone, digitaliques.</div>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Surveillance</span> des transaminases.</strong> Si <span class=\"kw-chiffre\">3-5N</span> → arrêt du <span class=\"kw-ttt\">PZA</span> ; si <span class=\"kw-chiffre\">&gt; 5N</span> → arrêt de l'<span class=\"kw-ttt\">INH</span> et du PZA. L'<span class=\"kw-ttt\">éthambutol</span> est arrêté dès la confirmation de la sensibilité à l'<span class=\"kw-ttt\">isoniazide</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Altération chronique de la vision · 177 — Anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":5},{"id":"159-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge des sujets contacts et d’isolement du patient","contenu":"<h4><span class=\"kw-def\">Isolement</span> du patient</h4>\n      <p><span class=\"kw-alerte\">Précautions Air</span> en cas d'<span class=\"kw-alerte\">hospitalisation</span> pour <span class=\"kw-def\">tuberculose</span> pulmonaire :</p>\n      <ul>\n        <li>Chambre individuelle, porte fermée, à <strong>pression négative</strong> (ou à défaut bien aérée).</li>\n        <li>Personnel et visiteurs : masque <span class=\"kw-def\">FFP2</span> ; patient : masque chirurgical lors des déplacements, déplacements limités.</li>\n        <li><strong>Levée des précautions</strong> — généralement après <span class=\"kw-chiffre\">≈ 15 jours</span> de traitement : apyrexie + régression de la <span class=\"kw-clinique\">toux</span> + négativation de l'examen direct.</li>\n      </ul>\n      <h4>Sujets contacts</h4>\n      <p>L'<span class=\"kw-def\">enquête autour d'un cas</span> est coordonnée par le <span class=\"kw-def\">CLAT</span> (centre de lutte antituberculeuse). Le risque d'infection des contacts dépend de la <strong>contagiosité du cas</strong> (cas <span class=\"kw-alerte\">bacillifère</span> = examen direct positif, <span class=\"kw-clinique\">toux importante</span>, <span class=\"kw-radio\">caverne</span> ; la <span class=\"kw-alerte\">tuberculose laryngée</span> est très bacillifère), de la <strong>période de contagiosité</strong> — <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> précédant le diagnostic — et du degré de proximité ci-dessous :</p>\n      <table >\n        <thead><tr><th>Type de <span class=\"kw-def\">contact</span></th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Étroit</strong></td><td>Partage du même lieu fermé plusieurs heures par jour (famille, classe, bureau)</td></tr>\n          <tr><td><strong>Régulier</strong></td><td>Partage régulier du même lieu fermé (domicile, cantine, atelier)</td></tr>\n          <tr><td><strong>Occasionnel</strong></td><td>Partage occasionnel — le <span class=\"kw-def\">dépistage</span> systématique ne concerne que <span class=\"kw-clinique\">les</span> contacts <strong>étroits et réguliers</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Modalités du <span class=\"kw-def\">dépistage</span> :</strong> examen clinique + <span class=\"kw-imagerie\">RXT</span> dès que possible (recherche d'une TM) ; si négatif, sujet revu à <span class=\"kw-chiffre\">8 semaines</span> du dernier <span class=\"kw-def\">contact</span> pour rechercher une ITL (<span class=\"kw-bio\">IGRA</span> ou <span class=\"kw-bio\">IDR</span>). Objectif : <span class=\"kw-def\">chimioprophylaxie</span> des ITL et traitement précoce des TM dépistées.</p>\n      <div class=\"callout callout-info\"><strong>Chez l'enfant.</strong> <span class=\"kw-def\">Dépistage</span> initié <span class=\"kw-chiffre\">&lt; 2 semaines</span> après l'identification du cas index, l'enfant <span class=\"kw-chiffre\">&lt; 5 ans</span> étant prioritaire. L'enfant <span class=\"kw-chiffre\">&lt; 2 ans</span> ou immunodéprimé reçoit une <strong><span class=\"kw-def\">chimioprophylaxie</span></strong> jusqu'à la <span class=\"kw-def\">réévaluation</span> à<span class=\"kw-chiffre\"> 8-12 semaines</span>.</div>","frequence":3},{"id":"159-16","rang":"A","rubrique":"Prise en charge","titre":"Savoir que la tuberculose est une maladie à déclaration obligatoire","contenu":"<p>La <span class=\"kw-def\">tuberculose</span> est une <span class=\"kw-def\">maladie à déclaration obligatoire (DO)</span> à l'<span class=\"kw-def\">ARS</span>. Deux situations relèvent de la <span class=\"kw-def\">DO</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Tuberculose</span> maladie</strong> confirmée <strong>ou suspectée</strong> — <span class=\"kw-alerte\">même sans preuve bactériologique</span> → objectif : identifier <span class=\"kw-clinique\">les</span> sujets contaminés.</li>\n        <li><strong>ITL chez le sujet de <span class=\"kw-chiffre\">&lt; 18 ans</span></strong> → objectif : identifier le sujet contaminant.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Procédure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Signalement</span> nominatif</strong></td><td><span class=\"kw-alerte\">Sans délai</span> à l'<span class=\"kw-def\">ARS</span>, par tout moyen (pas de formulaire type) ; déclenche le signalement au <span class=\"kw-def\">CLAT</span> et l'enquête autour du cas</td></tr>\n          <tr><td><strong>Notification anonyme</strong></td><td>Sur formulaire type ; information relayée à <span class=\"kw-def\">Santé Publique France</span>, à visée épidémiologique</td></tr>\n          <tr><td><strong>Déclaration des issues de traitement</strong></td><td><span class=\"kw-chiffre\">9 à 12 mois</span> après la <span class=\"kw-def\">DO</span> ; anonyme ; mesure la proportion de patients ayant achevé leur traitement</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La déclaration ne nécessite <span class=\"kw-alerte\">aucune preuve bactériologique</span> : une <span class=\"kw-def\">tuberculose</span> maladie simplement <strong>suspectée</strong> doit être déclarée. Et ne pas oublier la <span class=\"kw-def\">DO</span> de toute <strong>ITL de l'enfant de &lt;<span class=\"kw-chiffre\"> 18 ans</span></strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 178 — Risques émergents, bioterrorisme</em></p>","frequence":6},{"id":"159-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention vaccinale de la tuberculose","contenu":"<p>Le <span class=\"kw-ttt\">BCG</span> est un <strong>vaccin vivant atténué</strong> dérivé d'un isolat de <em>M. bovis</em> ayant perdu sa virulence.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Voie</strong></td><td>Injection <strong>intradermique</strong> dans le deltoïde (jamais en IM)</td></tr>\n          <tr><td><strong>Efficacité</strong></td><td>Protection de l'enfant ≈ <span class=\"kw-chiffre\">80 %</span> contre la <span class=\"kw-alerte\">méningite</span> et la <span class=\"kw-alerte\">miliaire</span> tuberculeuses ; protection controversée chez l'adulte</td></tr>\n          <tr><td><strong>Indications</strong></td><td>N'est <strong>plus obl<span class=\"kw-chiffre\">iga</span>toire</strong> — seulement <span class=\"kw-def\">recommandé</span> : enfants à risque (né ou parent originaire d'un pays d'endémie, ATCD familiaux de TB, résidence Île-de-France / Guyane / Mayotte, conditions socio-économiques précaires) et professionnels de santé</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indications</span>.</strong> <span class=\"kw-ci\">Infection VIH</span> (enfant infecté <strong>ou né de mère <span class=\"kw-etio\">VIH</span>+</strong>) ; <span class=\"kw-ci\">déficits immunitaires</span> congénitaux ou <span class=\"kw-etio\">acquis</span> ; <span class=\"kw-ci\">traitements immunosuppresseurs</span> ; <span class=\"kw-ci\">dermatoses étendues évolutives</span>.</div>\n      <p><strong>Effets indésirables :</strong> réaction <span class=\"kw-etio\">inflammatoire</span> locale retardée (induration puis <span class=\"kw-clinique\">ulcération</span> &lt;<span class=\"kw-chiffre\"> 1 cm</span>) avec <span class=\"kw-clinique\">adénopathie satellite</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-5 mois</span> ; rarement <span class=\"kw-alerte\">BCGite disséminée</span> (sujet immunodéprimé).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":3}],"astuces":[],"strategie":{"urgence":"<p><strong>Formes à <span class=\"kw-alerte\">risque vital</span></strong></p><ul><li><span class=\"kw-def\">Miliaire tuberculeuse</span> : <span class=\"kw-alerte\">décès en l’absence de traitement adapté précoce</span> → quadrithérapie débutée sans attendre</li><li><span class=\"kw-def\">Tuberculose neuro-méningée</span> : <span class=\"kw-alerte\">décès ~50 %</span>, <span class=\"kw-alerte\">séquelles neurologiques ~50 %</span> → <span class=\"kw-ttt\">corticothérapie</span> systématique</li><li><span class=\"kw-clinique\">Hémoptysie grave</span>, <span class=\"kw-alerte\">SDRA</span>, <span class=\"kw-alerte\">tamponnade</span> ou <span class=\"kw-alerte\">compression médullaire</span> : urgences propres aux localisations</li></ul><p><strong>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire sans délai</strong></p><ul><li><span class=\"kw-def\">Signalement nominatif</span> <strong>sans délai</strong> à l’<span class=\"kw-def\">ARS</span> (par tout moyen) → déclenche le <span class=\"kw-def\">signalement</span> au <span class=\"kw-def\">CLAT</span> et l’enquête autour du cas</li><li>TM confirmée <strong>ou seulement suspectée</strong>, <span class=\"kw-alerte\">même sans preuve bactériologique</span> ; ainsi que toute <span class=\"kw-def\">ITL</span> de l’enfant <span class=\"kw-chiffre\">&lt; 18 ans</span></li></ul><p><strong>Délais clés</strong></p><ul><li><span class=\"kw-bio\">Examen direct</span> (<span class=\"kw-bio\">Ziehl-Neelsen</span>) : résultat en quelques <span class=\"kw-chiffre\">heures</span></li><li><span class=\"kw-bio\">Test génotypique (PCR)</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 72 h</span> sur tout examen direct ou culture positif → traitement adapté en <span class=\"kw-chiffre\">24-48 h</span></li><li>Levée des <span class=\"kw-ttt\">précautions Air</span> après <span class=\"kw-chiffre\">~15 j</span> de traitement (apyrexie + régression de la <span class=\"kw-clinique\">toux</span> + négativation de l’examen direct)</li><li><span class=\"kw-def\">Dépistage</span> des sujets contacts (enfant) initié <span class=\"kw-chiffre\">&lt; 2 semaines</span> après identification du cas index</li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> initiale :</strong> tout malade suspect de <span class=\"kw-def\">tuberculose</span> pulmonaire, et toute suspicion de TM de l’enfant → bilan en milieu hospitalier avec <span class=\"kw-ttt\">isolement respiratoire de type air</span>.<br><strong>Précautions <span class=\"kw-def\">Air</span> :</strong> chambre individuelle à <span class=\"kw-chiffre\">pression négative</span>, porte fermée ; <span class=\"kw-ttt\">masque FFP2</span> pour soignants et visiteurs ; <span class=\"kw-ttt\">masque chirurgical</span> pour le patient en déplacement (déplacements limités).<br><strong>Levée des précautions :</strong> généralement après <span class=\"kw-chiffre\">~15 j</span> de traitement — apyrexie + régression de la <span class=\"kw-clinique\">toux</span> + négativation de l’examen direct (ou d’emblée à <span class=\"kw-chiffre\">15 j</span> si examen direct négatif au départ).<br><strong>MDR / XDR :</strong> hospitalisation en service spécialisé, avec respect strict des <span class=\"kw-ttt\">précautions Air</span>.<br><strong>Ambulatoire possible :</strong> <span class=\"kw-def\">ITL</span> et TM non compliquée de l’enfant ; éviction de collectivité jusqu’au certificat médical de non-contagiosité.<br><strong>Social :</strong> prise en charge à <span class=\"kw-chiffre\">100 %</span> (<span class=\"kw-def\">ALD</span>).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Détresse respiratoire</span> / <span class=\"kw-alerte\">SDRA</span> (miliaire tuberculeuse)</li><li><span class=\"kw-alerte\">Hémoptysie grave</span></li><li><span class=\"kw-alerte\">Troubles de la vigilance</span>, atteinte des nerfs crâniens (<span class=\"kw-alerte\">paralysie oculomotrice</span>, <span class=\"kw-alerte\">paralysie faciale</span>) et troubles <span class=\"kw-alerte\">neurovégétatifs</span> → <span class=\"kw-alerte\">méningite</span> basilaire</li><li><span class=\"kw-alerte\">Tamponnade</span> ou <span class=\"kw-alerte\">constriction péricardique</span> (péricardite tuberculeuse)</li><li><span class=\"kw-alerte\">Compression médullaire</span> ou <span class=\"kw-alerte\">épidurite</span> (mal de Pott)</li><li>Enfant : <span class=\"kw-alerte\">compression des voies aériennes</span> par <span class=\"kw-clinique\">adénopathies</span> (<span class=\"kw-ttt\">réduction</span> <span class=\"kw-chiffre\">&gt; 50 %</span> du calibre bronchique → atélectasie, emphysème obstructif)</li><li>Nourrisson <span class=\"kw-chiffre\">&lt; 3 mois</span> : aspect <span class=\"kw-alerte\">pseudo-septique</span> avec <span class=\"kw-alerte\">hépato-splénomégalie</span></li><li>Sous traitement : <span class=\"kw-alerte\">cytolyse hépatique majeure</span> / <span class=\"kw-chiffre\">transaminases &gt; 5N</span> ; <span class=\"kw-alerte\">dyschromatopsie rouge-vert</span> (névrite optique à l’<span class=\"kw-ttt\">éthambutol</span>)</li></ul>","principes":"<p><strong>Principes :</strong> <span class=\"kw-ttt\">polythérapie obligatoire</span> (prévient l’émergence de résistances), <strong>observance capitale</strong>, prise <strong>unique quotidienne à jeun</strong>, traitement <strong>prolongé</strong>, adapté à l’<span class=\"kw-bio\">antibiogramme</span> dès réception — <span class=\"kw-ttt\">arrêt de l’éthambutol</span> dès confirmation de la sensibilité à l’<span class=\"kw-ttt\">isoniazide</span>.<br><strong><span class=\"kw-ttt\">Corticothérapie</span> adjuvante :</strong> <span class=\"kw-ttt\">systématique</span> dans la forme <span class=\"kw-def\">neuro-méningée</span> ; proposée dans la <span class=\"kw-def\">péricardite</span> ; à discuter si <span class=\"kw-def\">miliaire</span>, <span class=\"kw-alerte\">signes de gravité</span> ou compression mécanique.</p><p><strong>Schémas selon la forme (adulte)</strong></p><ul><li>Forme commune : quadrithérapie <span class=\"kw-ttt\">2 RHZE</span> (<span class=\"kw-ttt\">INH + RMP + EMB + PZA</span>, <span class=\"kw-chiffre\">2 mois</span>) puis bithérapie <span class=\"kw-ttt\">4 RH</span> (<span class=\"kw-ttt\">INH + RMP</span>, <span class=\"kw-chiffre\">4 mois</span>) → <span class=\"kw-chiffre\">6 mois</span> au total</li><li>Forme neuro-méningée : <span class=\"kw-ttt\">2 RHZE</span> puis <span class=\"kw-ttt\">RH</span> pendant <span class=\"kw-chiffre\">7-10 mois</span> → <span class=\"kw-chiffre\">9-12 mois</span> + <span class=\"kw-ttt\">corticothérapie</span> systématique</li><li>Péricardite : antituberculeux + <span class=\"kw-ttt\">corticoïdes</span> (<span class=\"kw-ttt\">prednisone</span>), traitement prolongé <span class=\"kw-chiffre\">1 an</span></li><li>Schéma alternatif si <span class=\"kw-ci\">contre-indication au PZA</span> : <span class=\"kw-ttt\">2 RHE</span> puis <span class=\"kw-ttt\">7 RH</span> → <span class=\"kw-chiffre\">9 mois</span></li><li>Multi-résistance (<span class=\"kw-def\">MDR</span>/<span class=\"kw-def\">XDR</span>) : antituberculeux de <span class=\"kw-ttt\">2e ligne</span> (<span class=\"kw-ttt\">fluoroquinolones</span>, <span class=\"kw-ttt\">aminosides</span>) pendant <span class=\"kw-chiffre\">18-24 mois</span>, en service spécialisé</li></ul><p><strong>Enfant</strong></p><ul><li>TM non compliquée (<span class=\"kw-chiffre\">3 mois</span>-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>16</span> ans</span>) : <span class=\"kw-ttt\">trithérapie</span> <span class=\"kw-ttt\">2 RHZ</span> (<span class=\"kw-ttt\">INH + RMP + PZA</span>, <span class=\"kw-chiffre\">2 mois</span>) puis <span class=\"kw-ttt\">2 RH</span> (<span class=\"kw-chiffre\">2 mois</span>) → <span class=\"kw-chiffre\">4 mois</span></li><li>Autres situations : <span class=\"kw-ttt\">2 RHZE</span> (ajout <span class=\"kw-ttt\">éthambutol</span>) puis <span class=\"kw-ttt\">4 RH</span></li><li><span class=\"kw-def\">ITL</span> de l’enfant : <span class=\"kw-ttt\">INH + RMP</span> pendant <span class=\"kw-chiffre\">3 mois</span>, 1×/j le matin à jeun, dose adaptée au poids</li><li><span class=\"kw-ttt\">Corticothérapie</span> <span class=\"kw-clinique\">les</span> 1res semaines si compression des voies aériennes (<span class=\"kw-chiffre\">&gt; 50 %</span> du calibre) ou atteinte méningée/péricardique</li></ul><p><strong><span class=\"kw-def\">Chimioprophylaxie</span> de l’ITL (adulte)</strong></p><ul><li><span class=\"kw-ttt\">Isoniazide</span> seul pendant <span class=\"kw-chiffre\">6 mois</span></li><li><span class=\"kw-ttt\">Rifampicine</span> seule pendant <span class=\"kw-chiffre\">4 mois</span></li><li><span class=\"kw-ttt\">Rifampicine + isoniazide</span> pendant <span class=\"kw-chiffre\">3-4 mois</span></li></ul><p><strong><span class=\"kw-ci\">Bilan pré-thérapeutique</span></strong></p><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">bilan rénal</span> (<span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">DFG</span>), <span class=\"kw-bio\">transaminases</span>, <span class=\"kw-bio\">uricémie</span></li><li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span> proposées systématiquement</li><li><span class=\"kw-imagerie\">Examen ophtalmologique</span> avant <span class=\"kw-ttt\">éthambutol</span> (champ visuel, vision des couleurs) ; <span class=\"kw-bio\">β-hCG</span> si femme en âge de procréer</li></ul><p><strong>Adaptation au <span class=\"kw-def\">terrain</span></strong></p><ul><li><span class=\"kw-ci\">Grossesse</span> : traitement identique (pas de <span class=\"kw-ci\">tératogénicité</span>) + <span class=\"kw-ttt\">vitamine B6</span> sous <span class=\"kw-ttt\">INH</span>, <span class=\"kw-ttt\">vitamine K1</span> sous <span class=\"kw-ttt\">RMP</span> au dernier trimestre</li><li><span class=\"kw-ci\">Insuffisance hépatique</span> : <span class=\"kw-ci\">pas de PZA si transaminases &gt; 3N</span>, <span class=\"kw-ci\">pas d’INH si &gt; 5N</span></li><li><span class=\"kw-ci\">Insuffisance rénale</span> : adapter <span class=\"kw-ttt\">PZA</span> et <span class=\"kw-ttt\">EMB</span> si <span class=\"kw-chiffre\">&lt; 30 mL/min</span></li></ul>","suivi":"<p><strong>Efficacité :</strong> amélioration clinique (<span class=\"kw-chiffre\">J15, M1, M2, M4, M6…</span>), <span class=\"kw-imagerie\">RXT</span> et bactériologique (recherche de BK à <span class=\"kw-chiffre\">J15</span>, <span class=\"kw-chiffre\">M1</span> jusqu’à négativation).<br><strong>Tolérance hépatique :</strong> <span class=\"kw-bio\">transaminases</span> à <span class=\"kw-chiffre\">J7-J14</span>, <span class=\"kw-chiffre\">J30</span> puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 mois</span> — <span class=\"kw-chiffre\">3-5N</span> → <span class=\"kw-ttt\">arrêt du PZA</span> (<span class=\"kw-ttt\">trithérapie</span> <span class=\"kw-chiffre\">2 mois</span> puis bithérapie <span class=\"kw-chiffre\">7 mois</span>) ; <span class=\"kw-chiffre\">&gt; 5N</span> → <span class=\"kw-ttt\">arrêt de l’INH et du PZA</span> ; <span class=\"kw-alerte\">cytolyse majeure</span> → <span class=\"kw-ttt\">arrêt de tous les antituberculeux</span> + <span class=\"kw-ttt\">pharmacovigilance</span> + avis <span class=\"kw-chiffre\">2e ligne</span>.<br><strong>Autres examens :</strong> <span class=\"kw-bio\">NFS</span> et <span class=\"kw-bio\">créatinine</span> à <span class=\"kw-chiffre\">J7-J14</span> et <span class=\"kw-chiffre\">J30</span> ; <span class=\"kw-imagerie\">examen ophtalmologique</span> mensuel sous <span class=\"kw-ttt\">éthambutol</span> (champ visuel, vision des couleurs - Farnsworth, fond d’œil).<br><strong>Observance :</strong> comptage des boîtes, <span class=\"kw-bio\">dosages sériques</span> si doute, vérification de la <span class=\"kw-clinique\">coloration orange des urines</span> sous <span class=\"kw-ttt\">rifampicine</span> ; recherche active du patient perdu de vue.<br><strong>Enfant :</strong> <span class=\"kw-def\">surveillance</span> clinique mensuelle ; <span class=\"kw-bio\">transaminases</span> toutes les <span class=\"kw-chiffre\">2 semaines</span> (du fait du PZA) ; pas de bilan <span class=\"kw-ttt\">biologique</span> systématique pour l’ITL (sauf hépatopathie connue).<br><strong>Issues de traitement :</strong> déclaration anonyme à <span class=\"kw-chiffre\">9-12 mois</span> de la déclaration obl<span class=\"kw-chiffre\">iga</span>toire.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-159.pdf","label":"Collège Pilly — Tuberculose (item 159, PDF)"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/tuberculose","label":"Collège Pédiatrie — Tuberculose"},{"href":"https://www.hypocampus.fr/home/#/book/6439/chaptergroup/761416?chapter=46924&target=102957","label":"Hypocampus — Tuberculose (livre 6439)"},{"href":"https://www.hypocampus.fr/home/#/book/6563/chaptergroup/1145170?chapter=42965","label":"Hypocampus — Tuberculose (livre 6563)"},{"href":"https://www.hypocampus.fr/home/#/book/7145/chaptergroup/858214?chapter=48485&section=212477","label":"Hypocampus — Tuberculose (livre 7145)"},{"href":"https://www.hypocampus.fr/home/#/book/7145/chaptergroup/858214?chapter=48485","label":"Hypocampus — Tuberculose (livre 7145, sect.)"},{"href":"https://www.hypocampus.fr/home/#/book/6439/chaptergroup/761416?chapter=46924&section=197604","label":"Hypocampus — Tuberculose (livre 6439, sect.)"},{"href":"https://www.hypocampus.fr/home/#/book/7145/chaptergroup/858721?chapter=42965&section=175899","label":"Hypocampus — Tuberculose (livre 7145, sect. 2)"},{"href":"https://www.hypocampus.fr/home/#/book/6563/chaptergroup/1145170?chapter=42965&section=175901","label":"Hypocampus — Tuberculose (livre 6563, sect.)"},{"href":"https://www.hypocampus.fr/home/#/book/7008/chaptergroup/848878?chapter=48366&target=144967","label":"Hypocampus — Tuberculose (livre 7008)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Tuberculose maladie confirmée — Choix du schéma antituberculeux","detail":"<h4>CAT — traitement de la <span class=\"kw-etio\">tuberculose</span> maladie — Choix du schéma selon la résistance, la forme clinique et la tolérance hépatique</h4>","branches":[{"to":"t-mdr","label":"Souche multi-résistante — résistance à INH + RMP (MDR/XDR)","color":"red"},{"to":"q-forme","label":"Souche sensible aux antituberculeux de 1re ligne","color":"green"}]},{"id":"t-mdr","kind":"terminal","label":"Antituberculeux de 2e ligne — 18 à 24 mois","color":"red","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">MDR</span> = résistance à l’<span class=\"kw-ttt\">INH</span> + la <span class=\"kw-ttt\">RMP</span> ; <span class=\"kw-def\">XDR</span> = MDR + résistance à toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">fluoroquinolones</span> + <span class=\"kw-chiffre\">≥ 1</span> injectable de <span class=\"kw-chiffre\">2e ligne</span> (<span class=\"kw-alerte\">mortalité élevée</span>).</li></ul><h4>Traitement</h4><ul><li>Antituberculeux de <span class=\"kw-ttt\">2e ligne</span> : <span class=\"kw-ttt\">fluoroquinolones</span> (<span class=\"kw-ttt\">moxifloxacine</span>, <span class=\"kw-ttt\">lévofloxacine</span>), <span class=\"kw-ttt\">aminosides</span> (<span class=\"kw-ttt\">amikacine</span>, <span class=\"kw-ttt\">capréomycine</span>, <span class=\"kw-ttt\">kanamycine</span>)</li><li>Durée prolongée <span class=\"kw-chiffre\">18 à 24 mois</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> en service spécialisé, <span class=\"kw-ttt\">précautions Air</span> strictes</li><li>Souche adressée au <span class=\"kw-def\">CNR</span> des mycobactéries pour l’<span class=\"kw-bio\">antibiogramme</span> de <span class=\"kw-chiffre\">2e ligne</span></li><li>FR principal = <span class=\"kw-alerte\">défaut d’observance</span> ; origines géographiques à risque (ex-URSS, Chine, Inde)</li></ul>"},{"id":"q-forme","kind":"decision","label":"Quelle forme clinique ? — Localisation et dissémination orientent durée et corticothérapie","branches":[{"to":"q-hepato","label":"Pulmonaire commune ou extra-pulmonaire (hors neuro-méninges / péricarde)","color":"green"},{"to":"t-neuro","label":"Forme neuro-méningée","color":"amber"},{"to":"t-pericardite","label":"Péricardite tuberculeuse","color":"amber"},{"to":"t-miliaire","label":"Miliaire / forme disséminée","color":"amber"}]},{"id":"q-hepato","kind":"decision","label":"Tolérance hépatique ? — Bilan pré-thérapeutique puis suivi des transaminases","branches":[{"to":"t-standard","label":"Bilan hépatique normal (transaminases inférieures à 3N)","color":"green"},{"to":"t-sans-pza","label":"Transaminases 3-5N ou contre-indication au PZA","color":"amber"},{"to":"t-hepatotox","label":"Transaminases supérieures à 5N ou cytolyse majeure","color":"red"}]},{"id":"t-standard","kind":"terminal","label":"Schéma standard 2 RHZE + 4 RH (6 mois)","color":"green","detail":"<h4>Traitement</h4><ul><li>Quadrithérapie <span class=\"kw-ttt\">2 RHZE</span> : <span class=\"kw-ttt\">INH + RMP + EMB + PZA</span> pendant <span class=\"kw-chiffre\">2 mois</span></li><li>puis bithérapie <span class=\"kw-ttt\">4 RH</span> : <span class=\"kw-ttt\">INH + RMP</span> pendant <span class=\"kw-chiffre\">4 mois</span></li><li>Durée totale <span class=\"kw-chiffre\">6 mois</span></li></ul><h4>Modalités</h4><ul><li>Prise <strong>unique quotidienne, à jeun</strong> (<span class=\"kw-chiffre\">30 min-1 h</span> avant le repas)</li><li><span class=\"kw-ttt\">Polythérapie obligatoire</span> ; observance capitale</li><li><span class=\"kw-ttt\">Arrêt de l’éthambutol</span> dès confirmation de la sensibilité à l’<span class=\"kw-ttt\">isoniazide</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Transaminases</span> à <span class=\"kw-chiffre\">J7-J14</span>, <span class=\"kw-chiffre\">J30</span> puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 mois</span></li><li><span class=\"kw-imagerie\">Examen ophtalmologique</span> mensuel sous <span class=\"kw-ttt\">EMB</span></li><li>Levée des <span class=\"kw-ttt\">précautions Air</span> vers <span class=\"kw-chiffre\">J15</span></li></ul>"},{"id":"t-sans-pza","kind":"terminal","label":"Schéma sans pyrazinamide — 9 mois","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-ci\">Contre-indication au PZA</span> (<span class=\"kw-alerte\">insuffisance hépatocellulaire</span>) ou <span class=\"kw-bio\">transaminases</span> entre <span class=\"kw-chiffre\">3 et 5N</span> sous traitement → <span class=\"kw-ttt\">arrêt du PZA</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Trithérapie</span> <span class=\"kw-ttt\">INH + RMP + EMB</span> pendant <span class=\"kw-chiffre\">2 mois</span></li><li>puis bithérapie <span class=\"kw-ttt\">INH + RMP</span> pendant <span class=\"kw-chiffre\">7 mois</span></li><li>Durée totale <span class=\"kw-chiffre\">9 mois</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ci\"><span class=\"kw-def\">Surveillance</span> hépatique</span> rapprochée jusqu’à normalisation des <span class=\"kw-bio\">transaminases</span>.</li></ul>"},{"id":"t-hepatotox","kind":"terminal","label":"Hépatotoxicité grave — arrêt et avis spécialisé","color":"red","detail":"<h4>Conduite immédiate</h4><ul><li><span class=\"kw-bio\">Transaminases</span> <span class=\"kw-chiffre\">&gt; 5N</span> → <span class=\"kw-ttt\">arrêt de l’INH et du PZA</span> ; <span class=\"kw-alerte\">cytolyse majeure</span> ou <span class=\"kw-alerte\">signe de gravité</span> → <span class=\"kw-ttt\">arrêt de tous les antituberculeux</span>.</li></ul><h4>Suite</h4><ul><li>Déclaration de <span class=\"kw-ttt\">pharmacovigilance</span></li><li>Avis spécialisé pour antituberculeux de <span class=\"kw-ttt\">2e ligne</span></li><li>Après normalisation : réintroduction prudente de l’<span class=\"kw-ttt\">INH</span> à demi-dose avec <span class=\"kw-bio\">dosages sériques</span></li></ul>"},{"id":"t-neuro","kind":"terminal","label":"Schéma prolongé 9-12 mois + corticothérapie","color":"amber","detail":"<h4>Traitement</h4><ul><li>Quadrithérapie <span class=\"kw-ttt\">INH + RMP + EMB + PZA</span> pendant <span class=\"kw-chiffre\">2 mois</span></li><li>puis bithérapie <span class=\"kw-ttt\">INH + RMP</span> pendant <span class=\"kw-chiffre\">7-10 mois</span></li><li>Durée totale <span class=\"kw-chiffre\">9-12 mois</span></li></ul><h4><span class=\"kw-ttt\">Corticothérapie</span></h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> systématique.</li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li><span class=\"kw-alerte\">Décès ~50 %</span>, <span class=\"kw-alerte\">séquelles neurologiques ~50 %</span> → <span class=\"kw-alerte\">urgence</span> thérapeutique ; surveiller <span class=\"kw-bio\">hyponatrémie</span> (<span class=\"kw-bio\">SIADH</span>).</li></ul>"},{"id":"t-pericardite","kind":"terminal","label":"Antituberculeux + corticoïdes, prolongés 1 an","color":"amber","detail":"<h4>Traitement</h4><ul><li>Antituberculeux identiques à toute <span class=\"kw-etio\">tuberculose</span> mais <strong>prolongés <span class=\"kw-chiffre\">1 an</span></strong></li><li>Associés aux <span class=\"kw-ttt\">corticoïdes</span> (<span class=\"kw-ttt\">prednisone</span>)</li></ul><h4>Objectif</h4><ul><li>Réduire le risque d’<span class=\"kw-clinique\">évolution</span> vers une <span class=\"kw-alerte\">constriction péricardique</span> ; surveiller <span class=\"kw-alerte\">tamponnade</span> et <span class=\"kw-alerte\">récidive</span>.</li></ul>"},{"id":"t-miliaire","kind":"terminal","label":"Schéma standard 6 mois, débuté sans attendre","color":"amber","detail":"<h4>Traitement</h4><ul><li>Schéma standard <span class=\"kw-ttt\">2 RHZE + 4 RH</span> (<span class=\"kw-chiffre\">6 mois</span>), débuté <strong>sans délai</strong> (<span class=\"kw-alerte\">décès en l’absence de traitement précoce</span>).</li></ul><h4><span class=\"kw-ttt\">Corticothérapie</span></h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> à discuter : miliaire, <span class=\"kw-alerte\">signes de gravité</span>, compression mécanique.</li></ul><h4>Bilan</h4><ul><li>Prélèvements multiviscéraux (<span class=\"kw-bio\">LBA</span>, <span class=\"kw-bio\">hémocultures</span> sur milieu spécifique, <span class=\"kw-bio\">ECBU</span>, <span class=\"kw-bio\">myéloculture</span>) ; rechercher un <span class=\"kw-alerte\">SDRA</span> et une atteinte neuro-méningée.</li></ul>"}]},"cards":[]};